106→export function MessageBubble({ message, messageIndex }: { message: ChatMessage; messageIndex: number }) {
107→  const { t } = useTranslation();
108→  const { isStreaming, editMessage, deleteMessage } = useAgent();
109→  const [isEditing, setIsEditing] = useState(false);
110→  const [editText, setEditText] = useState(message.content);
111→  const [isConfirmingDelete, setIsConfirmingDelete] = useState(false);
112→  const textareaRef = useRef<HTMLTextAreaElement>(null);
113→
114→  const isUser = message.role === 'user';
115→  const hasSegments = !isUser && message.segments && message.segments.length > 0;
116→
117→  useEffect(() => {
118→    if (isEditing && textareaRef.current) {
119→      textareaRef.current.focus();
120→      textareaRef.current.selectionStart = textareaRef.current.value.length;
121→    }
122→  }, [isEditing]);
123→
124→  const handleEdit = () => {
125→    setEditText(message.content);
126→    setIsEditing(true);
127→    setIsConfirmingDelete(false);
128→  };
129→
130→  const handleCancelEdit = () => {
131→    setIsEditing(false);
132→    setEditText(message.content);
133→  };
134→
135→  const handleSaveEdit = () => {
136→    const trimmed = editText.trim();
137→    if (!trimmed || trimmed === message.content) {
138→      handleCancelEdit();
139→      return;
140→    }
141→    setIsEditing(false);
142→    editMessage(messageIndex, trimmed);
143→  };
144→
145→  const handleDeleteConfirm = () => {
146→    setIsConfirmingDelete(false);
147→    deleteMessage(messageIndex);
148→  };
149→
150→  const handleKeyDown = (e: React.KeyboardEvent) => {
151→    if (e.key === 'Escape') {
152→      handleCancelEdit();
153→    } else if (e.key === 'Enter' && !e.shiftKey && !e.nativeEvent.isComposing) {
154→      e.preventDefault();
155→      handleSaveEdit();
156→    }
157→  };
158→
159→  let streamingRemainder: string | undefined;
160→  if (hasSegments && message.isStreaming && message.content) {
161→    const segmentedText = message.segments!
162→      .filter((s) => s.type === 'thinking' || s.type === 'answer')
163→      .map((s) => s.text || '')
164→      .join('');
165→    const remaining = message.content.slice(segmentedText.length);
166→    if (remaining.trim()) {
167→      streamingRemainder = remaining;
168→    }
169→  }
170→
171→  const hasAnswer = hasSegments && message.segments!.some((s) => s.type === 'answer');
172→  const isInAnswerPhase = message.currentPhase === 'answer';
173→  const isThinkingPhase = !!message.isStreaming && !hasAnswer && !isInAnswerPhase;
174→
175→  const hasCharts = hasSegments && message.segments!.some(
176→    (s) => (s.type === 'tool' && s.toolResult?.chart_spec) || (s.type === 'subagent_end' && s.chart_spec)
177→  );
178→
179→  const answerBlockSegments = hasSegments
180→    ? message.segments!
181→        .filter((s) =>
182→          (s.type === 'answer' && s.text?.trim()) ||
183→          (s.type === 'subagent_end' && !s.chart_spec && s.text?.trim()) ||
184→          (s.type === 'tool' && s.toolResult?.chart_spec) ||
185→          (s.type === 'subagent_end' && s.chart_spec)
186→        )
187→        .map((s) => {
188→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && s.text && hasCharts) {
189→            return { ...s, text: stripChartSpecBlocks(s.text) };
190→          }
191→          return s;
192→        })
193→        .filter((s) => {
194→          // Remove text segments that became empty after stripping chart blocks
195→          if ((s.type === 'answer' || (s.type === 'subagent_end' && !s.chart_spec)) && !s.text?.trim()) {
196→            return false;
197→          }
198→          return true;
199→        })
200→    : [];
201→
202→  const questionSegments = hasSegments
203→    ? message.segments!.filter((s) => s.type === 'user_question' && s.questionData)
204→    : [];
205→
206→  return (
207→    <div className={`message-bubble message-bubble--${message.role}`}>
208→      <div className="message-bubble__header">
209→        {isUser ? t('you') : t('assistant')}
210→        {isUser && !isStreaming && !isEditing && !isConfirmingDelete && (
211→          <span className="message-bubble__actions">
212→            <button
213→              className="message-bubble__action-btn"
214→              onClick={handleEdit}
215→              title={t('editMessage')}
216→            >
217→              &#9998;
218→            </button>
219→            <button
220→              className="message-bubble__action-btn message-bubble__action-btn--delete"
221→              onClick={() => setIsConfirmingDelete(true)}
222→              title={t('deleteMessage')}
223→            >
224→              &#128465;
225→            </button>
226→          </span>
227→        )}
228→      </div>
229→
230→      {isUser && isConfirmingDelete && (
231→        <div className="message-bubble__confirm-delete">
232→          <span>{t('deleteConfirm')}</span>
233→          <div className="message-bubble__confirm-actions">
234→            <button
235→              className="message-bubble__confirm-btn message-bubble__confirm-btn--delete"
236→              onClick={handleDeleteConfirm}
237→            >
238→              {t('delete')}
239→            </button>
240→            <button
241→              className="message-bubble__confirm-btn"
242→              onClick={() => setIsConfirmingDelete(false)}
243→            >
244→              {t('cancel')}
245→            </button>
246→          </div>
247→        </div>
248→      )}
249→
250→      {isUser && isEditing ? (
251→        <div className="message-bubble__edit-mode">
252→          <textarea
253→            ref={textareaRef}
254→            className="message-bubble__edit-textarea"
255→            value={editText}
256→            onChange={(e) => setEditText(e.target.value)}
257→            onKeyDown={handleKeyDown}
258→            rows={3}
259→          />
260→          <div className="message-bubble__edit-actions">
261→            <button
262→              className="message-bubble__edit-btn message-bubble__edit-btn--save"
263→              onClick={handleSaveEdit}
264→            >
265→              {t('saveResend')}
266→            </button>
267→            <button
268→              className="message-bubble__edit-btn"
269→              onClick={handleCancelEdit}
270→            >
271→              {t('cancel')}
272→            </button>
273→          </div>
274→        </div>
275→      ) : hasSegments ? (
276→        <div className="message-bubble__segments">
277→          {!questionSegments.some((s) => !s.userAnswer) && (
278→            <ThinkingBlock
279→              segments={message.segments!}
280→              streamingRemainder={isThinkingPhase ? streamingRemainder : undefined}
281→              isThinkingPhase={isThinkingPhase}
282→              isAgentStreaming={!!message.isStreaming}
283→            />
284→          )}
285→          {questionSegments.map((seg, i) => (
286→            <div key={`question-${i}`} className="message-bubble__segment message-bubble__segment--question">
287→              <UserQuestion
288→                questionData={seg.questionData!}
289→                userAnswer={seg.userAnswer}
290→                userFreeText={seg.userFreeText}
291→              />
292→            </div>
293→          ))}
294→          {answerBlockSegments.length > 0 && (
295→            <div className="message-bubble__segment message-bubble__segment--answer">
296→              <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
297→              {answerBlockSegments.map((seg, i) => {
298→                // Chart segment (tool with chart_spec or subagent_end with chart_spec)
299→                if ((seg.type === 'tool' && seg.toolResult?.chart_spec) || (seg.type === 'subagent_end' && seg.chart_spec)) {
300→                  return (
301→                    <div key={`chart-${i}`} className="message-bubble__chart-in-answer">
302→                      {seg.type === 'tool' && seg.toolResult ? (
303→                        <InlineQueryResult result={seg.toolResult!} />
304→                      ) : seg.chart_spec ? (
305→                        <ChartWidget data={seg.chart_spec.data} layout={seg.chart_spec.layout} frames={seg.chart_spec.frames} />
306→                      ) : null}
307→                    </div>
308→                  );
309→                }
310→                // Text segment (answer or subagent_end without chart_spec)
311→                return (
312→                  <div key={`answer-${i}`} className="message-bubble__segment-content">
313→                    <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text!}</ReactMarkdown>
314→                  </div>
315→                );
316→              })}
317→            </div>
318→          )}
319→          {isInAnswerPhase && streamingRemainder?.trim() && (() => {
320→            const displayText = hasCharts ? stripChartSpecBlocks(streamingRemainder) : streamingRemainder;
321→            return displayText?.trim() ? (
322→              <div className="message-bubble__segment message-bubble__segment--answer">
323→                <div className="message-bubble__segment-label message-bubble__segment-label--answer">{t('answer')}</div>
324→                <div className="message-bubble__segment-content">
325→                  <ReactMarkdown remarkPlugins={[remarkGfm]}>{displayText}</ReactMarkdown>
326→                </div>
327→              </div>
328→            ) : null;
329→          })()}
330→          {message.isStreaming && !message.content && questionSegments.length === 0 && (
331→            <span className="message-bubble__typing">{t('thinking')}</span>
332→          )}
333→        </div>
334→      ) : (
335→        <>
336→          <div className="message-bubble__content">
337→            {message.content ? (
338→              <ReactMarkdown remarkPlugins={[remarkGfm]}>{message.content}</ReactMarkdown>
339→            ) : message.isStreaming ? (
340→              <span className="message-bubble__typing">{t('thinking')}</span>
341→            ) : null}
342→          </div>
343→          {message.toolCalls && message.toolCalls.length > 0 && (
344→            <div className="message-bubble__tools">
345→              {message.toolCalls.map((tc) => (
346→                <InlineQueryResult key={tc.toolCallId} result={tc} />
347→              ))}
348→            </div>
349→          )}
350→        </>
351→      )}
352→    </div>
353→  );
354→}
