588→  return (
589→    <AgentContext.Provider
590→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, respondToQuestion }}
591→    >
592→      {children}
593→    </AgentContext.Provider>
594→  );
